-- SQL*Plus WHENEVER commands end at the newline or an optional semicolon.
WHENEVER OSERROR EXIT
WHENEVER OSERROR EXIT SUCCESS
-- WARNING for OSERROR also works as of 19c (exit code 2), although not officially documented
WHENEVER OSERROR EXIT WARNING
WHENEVER OSERROR EXIT FAILURE ROLLBACK;
WHENEVER OSERROR EXIT 42 COMMIT
WHENEVER OSERROR EXIT -1 ROLLBACK
WHENEVER OSERROR EXIT +1
WHENEVER OSERROR EXIT exit_code
WHENEVER OSERROR EXIT :exit_code COMMIT
WHENEVER OSERROR CONTINUE
WHENEVER OSERROR CONTINUE COMMIT
WHENEVER OSERROR CONTINUE ROLLBACK;
WHENEVER OSERROR CONTINUE NONE

whenever sqlerror exit
WHENEVER SQLERROR EXIT SUCCESS COMMIT
WHENEVER SQLERROR EXIT FAILURE
WHENEVER SQLERROR EXIT WARNING ROLLBACK
WHENEVER SQLERROR EXIT 1
WHENEVER SQLERROR EXIT SQL.SQLCODE
WHENEVER SQLERROR EXIT sqlcode
WHENEVER SQLERROR EXIT :return_code
WHENEVER SQLERROR EXIT COMMIT
WHENEVER SQLERROR EXIT ROLLBACK
WHENEVER SQLERROR CONTINUE
WHENEVER SQLERROR CONTINUE COMMIT
WHENEVER SQLERROR CONTINUE ROLLBACK
WHENEVER SQLERROR CONTINUE NONE;

WHENEVER SQLERROR EXIT
SELECT 1 FROM dual;
WHENEVER SQLERROR EXIT
COMMIT;
WHENEVER SQLERROR EXIT -- A comment must not absorb the following statement.
SELECT 2 FROM dual;

WHENEVER OSERROR EXIT FAILURE -- The transaction option must stay on this line.
SELECT 4 FROM dual;

WHENEVER OSERROR CONTINUE -- The continue option must stay on this line.
SELECT 5 FROM dual;

WHENEVER SQLERROR EXIT FAILURE
-- Intermediate comment
SELECT 3 FROM dual;

WHENEVER OSERROR CONTINUE
ROLLBACK;
WHENEVER SQLERROR EXIT SQL.SQLCODE
BEGIN
    NULL;
END;
/
WHENEVER OSERROR EXIT FAILURE;
SHOW ERRORS;
WHENEVER SQLERROR CONTINUE
whenever sqlerror continue

WHENEVER /* inline comment */ SQLERROR EXIT /* status */ FAILURE ROLLBACK
WHENEVER   OSERROR   EXIT   42   COMMIT
WHENEVER SQLERROR EXIT; SELECT 6 FROM dual;

SELECT 'WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK'
FROM dual;
